head.script:
    	
	  	    var isMain = true;
	  	    var mainDivisionId="MBIS00000000000000";
	  	    var bannerBtm;
	  	    var popSlide;
	  	    var chartSlide;
	  	    var sWorkGbn = "BIS";  
	  	    var arrBoardInfo = ["1|MBIS01090010000000|/xml/board/BISItgtBoardViewFre.xml|8|/xml/board/BISItgtBoardListFre.xml|FRE","7|MBIS01020050000000|/xml/board/BISItgtBoardViewPDS.xml|1|/xml/board/BISItgtBoardListPDS.xml|PDS"];
           /*******************init******************************************************
             * function    : init
             * Description : sub main 초기화
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function init() {
            	menuSearch();
            	getIdxList();
            	getBoardList(0);
            	getPopupZoneList();
            	getReportCompLogoList();
            	getAnnItmList();
            	getKrxFurList();
            	makeFavorMenu();
            	logVisitCnt(mainDivisionId);
            	
            	var selectedMenu = getCookie("bisSelectedMenu");
            	(selectedMenu=="1") ? toggleMainMenu(false) :toggleMainMenu(true);
            }
           
           /*******************menuSearch******************************************************
             * function    : menuSearch
             * Description : 관리자 메뉴 검색
             * Parameter   : sWorkGbn(채널 구분)
             * Return      : null
            **************************************************************************/
            function menuSearch() {
		       setValue("BISComMenuDTO/workGb", "KOR");
		       BISComMenuDTO =  WebSquare.xml.indent( getInstanceNode("BISComMenuDTO") );
		       callProFrameAdvanced("BIS-COM","BISComMenuSO","selectMenuBIS",BISComMenuDTO,"respMenu", true);
            }
            
           /*******************getReportCompLogoList******************************************************
             * function    : getRptCompLogoList
             * Description : 보고회사로고리스트 조회
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function getReportCompLogoList() {
				var today = WebSquare.date.getCurrentServerDate( "yyyyMMdd" );
				setValue("reqRptComp/BISReportCompLogoDTO/standardDt",today);
				setValue("reqRptComp/BISReportCompLogoDTO/workGb",sWorkGbn);
				var BISReportCompLogoDTO = WebSquare.xml.indent(getInstanceNode("reqRptComp/BISReportCompLogoDTO"));
		        callProFrameAdvanced("BIS-KOFIABOND","BISMainSO","selectRptCompLogoList",BISReportCompLogoDTO,"respRptCompLogo");
            }

            /**************************************************************************
             * function    : callBack
             * Description : submission callBack 함수
             * Parameter   : retAction (실행 submission의 Action 값), rowCount(select 한 건수)
             * Return      : null
            **************************************************************************/  
            function callBack(svcId,fnId,strResp) {
		        if (svcId == "BISComMenuSO") {
					headerWrap.setSrc("/xml/header.xml");
		        } else if (svcId == "BISMainSO") {
		        	if(fnId == "selectRptCompLogoList"){
		        		makeBottomRoll();
		        	} else if(fnId == "selectPopupZoneList") {
		        		makePopupZone();
		        	} else if(fnId == "selectBoardList") {
		        		writeBoardList(strResp);
		        	} else if(fnId == "selectIdxList") {
		        		grdIdx.setXML( getInstanceNode("respIdx/root/message/BISMainIdxCompDTO/BISMainIdxListDTO") );
		        		chartShow();
		        	} else if(fnId == "selectAnnItmList") {
		        		grdAnnItm.setXML( getInstanceNode("respAnn/root/message/BISMainComListDTO") );
		        		txtAnnTime.setLabel( getTimeStr() );
		        	} else if(fnId == "selectKrxFurList") {
		        		grdFur.setXML( getInstanceNode("respFur/root/message/BISMainComListDTO") );
		        		txtFurTime.setLabel( getTimeStr() );
		        	} else if(fnId == "selectPrvMnyNtceList") {
		        		writePrvMnyNtceList();
		        	}
		        }
            }
            
           /*******************makeBottomRoll******************************************************
             * function    : makeBottomRoll
             * Description : 하단 배너 영역을 생성한다.
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function makeBottomRoll() {
             	var bottomBannerList = WebSquare.ModelUtil.findInstanceNodes("respRptCompLogo/root/message/BISReportCompLogoListDTO/BISReportCompLogoDTO");
                for (var i=0 ; i<bottomBannerList.length ; i++) {
                	genBtmRoll.insert();
                	
                	var imageTtl = WebSquare.xml.getValue( bottomBannerList[i], "imageTtl" );
                	var homepage = WebSquare.xml.getValue( bottomBannerList[i], "homepage" );
                	var fileNm = WebSquare.xml.getValue( bottomBannerList[i], "fileNm" );
                	
                	var objBtmRollA = genBtmRoll.getChild( i , "grpBtmRollA" );
                	var objImgBtmRoll = genBtmRoll.getChild( i , "imgBtmRoll" );
                	
                	objBtmRollA.setUserData( "homepage", homepage );
                	objImgBtmRoll.setAlt( imageTtl + " 배너 이미지" );
                	objImgBtmRoll.setSrc( "/webresource/reportCompImage/"+fileNm);
                }
				bannerBtm = new js_rolling(document.getElementById("genBtmRoll"));
				bannerBtm.set_direction(4);
				bannerBtm.time_dealy_pause = 0;	//하나의 대상이 새로 시작할 때 멈추는 시간, 0 이면 적용 안함
				bannerBtm.time_dealy = 0; 			//움직이는 타임딜레이
            }
            
           /*******************getPopupZoneList******************************************************
             * function    : getPopupZoneList
             * Description : 팝업존 리스트 가져오기
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function getPopupZoneList() {
               setValue("reqPopZone/BISPopupZoneDTO/workGb",sWorkGbn);
               var BISPopupZoneDTO = WebSquare.xml.indent(getInstanceNode("reqPopZone/BISPopupZoneDTO"));
		       callProFrameAdvanced("BIS-KOFIABOND","BISMainSO","selectPopupZoneList",BISPopupZoneDTO,"respPopupZone", true);
            }
            
           /*******************getBoardList******************************************************
             * function    : getBoardList
             * Description : 게시판 리스트 가져오기
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function getBoardList(tabIdx){
            	var boardId = arrBoardInfo[tabIdx].split("|")[0];
            	var resp = "respBoard"+tabIdx;
            	setValue("reqBoard/BISMainBoardDTO/boardId",boardId);
            	var BISMainBoardDTO = WebSquare.xml.indent(getInstanceNode("reqBoard/BISMainBoardDTO"));
		        callProFrameAdvanced("BIS-KOFIABOND","BISMainSO","selectBoardList",BISMainBoardDTO, resp,true);
            }
            
           /*******************selectPrvMnyNtceList******************************************************
             * function    : selectPrvMnyNtceList
             * Description : 채권공고 리스트 조회
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function getPrvMnyNtceList(){
		        callProFrameAdvanced("BIS-KOFIABOND","BISMainSO","selectPrvMnyNtceList","", "respPrvMnyNtce",true);
            }
            
            /*******************writeBoardList******************************************************
             * function    : writeBoardList
             * Description : 게시판 리스트 출력
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function writeBoardList(strResp){
		        var tmpObj;
		        var tabIdx = strResp.substring(9);
		        var boardInfo = arrBoardInfo[tabIdx].split("|");
		        var url="w2xPath="+boardInfo[2]+"&boardInfo="+boardInfo[0]+"&divisionId="+boardInfo[1]+"&topMenuIndex="+boardInfo[3]+"&boardTyp="+boardInfo[5];
		        var moreUrl="w2xPath="+boardInfo[4]+"&boardInfo="+boardInfo[0]+"&divisionId="+boardInfo[1]+"&topMenuIndex="+boardInfo[3];
		        
            	var genObj = WebSquare.util.getComponentById( "genBoard"+tabIdx );
            	var xmlNodes = WebSquare.ModelUtil.findInstanceNodes( strResp+"/root/message/BISMainBoardListDTO/BISMainBoardDTO" );
            	
                for (var i=0 ; i<xmlNodes.length ; i++) {
                	genObj.insert();
                	var statementId = WebSquare.xml.getValue( xmlNodes[i], "statementId" );
                	var title = WebSquare.xml.getValue( xmlNodes[i], "title" );
                	var registDt = WebSquare.xml.getValue( xmlNodes[i], "registDt" ).substring(0,8);
					var linkUrl=url+"&statementId="+statementId;
                	tmpObj = genObj.getChild( i , "genBoardA" );
                	tmpObj.setUserData("url",linkUrl);

                	tmpObj = genObj.getChild( i , "genBoardTitle" );
                	tmpObj.setLabel( title );

                	tmpObj = genObj.getChild( i , "genBoardRegDt" );
                	tmpObj.setLabel( registDt );
				}
               	tmpObj = WebSquare.util.getComponentById( "genBoardMoreA"+tabIdx );
               	tmpObj.setUserData("url",moreUrl);                	
				
				tabControl3.setUserData( "tab"+tabIdx , true );            	
            }
            
            /*******************writePrvMnyNtceList******************************************************
             * function    : writePrvMnyNtceList
             * Description : 채권공고 리스트 출력
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function writePrvMnyNtceList(){
		        var tmpObj;
		        var tabIdx = 2;

            	var genObj = WebSquare.util.getComponentById( "genBoard"+tabIdx );
            	var xmlNodes = WebSquare.ModelUtil.findInstanceNodes("respPrvMnyNtce/root/message/BISMainBoardListDTO/BISMainBoardDTO" );
            	
                for (var i=0 ; i<xmlNodes.length ; i++) {
                	genObj.insert();
                	var val1 = WebSquare.xml.getValue( xmlNodes[i], "val1" );
                	var val2 = WebSquare.xml.getValue( xmlNodes[i], "val2" );
                	var val3 = WebSquare.xml.getValue( xmlNodes[i], "val3" );
                	var val4 = WebSquare.xml.getValue( xmlNodes[i], "val4" );
                	var url = "'"+val1+"','"+val2+"','"+val3+"','"+val4+"'";
                	var title = WebSquare.xml.getValue( xmlNodes[i], "title" );
                	var registDt = WebSquare.xml.getValue( xmlNodes[i], "registDt" );

                	tmpObj = genObj.getChild( i , "genBoardA" );
                	tmpObj.setUserData("url",url);

                	tmpObj = genObj.getChild( i , "genBoardTitle" );
                	tmpObj.setLabel( title );

                	tmpObj = genObj.getChild( i , "genBoardRegDt" );
                	tmpObj.setLabel( registDt );
				}
               	tmpObj = WebSquare.util.getComponentById( "genBoardMoreA"+tabIdx );
               	tmpObj.setUserData("url","1,6");                	
				
				tabControl3.setUserData( "tab"+tabIdx , true );            	
            }            
            
           /*******************getIdxList******************************************************
             * function    : getIdxList
             * Description : 지수 리스트 조회
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function getIdxList(){
            	var today = WebSquare.date.getCurrentServerDate( "yyyyMMdd" );
                setValue("reqIdx/BISMainIdxDTO/standardDt",today);
            	var BISMainIdxDTO = WebSquare.xml.indent(getInstanceNode("reqIdx/BISMainIdxDTO"));
                callProFrameAdvanced("BIS-KOFIABOND","BISMainSO","selectIdxList",BISMainIdxDTO, "respIdx",true);
            }
            
           /*******************getAnnItmList******************************************************
             * function    : getAnnItmList
             * Description : 최종호가수익률 리스트 조회
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function getAnnItmList(){
            	var today = WebSquare.date.getCurrentServerDate( "yyyyMMdd" );
                setValue("reqAnnItm/BISMainComDTO/standardDt",today);
            	var BISMainComDTO = WebSquare.xml.indent(getInstanceNode("reqAnnItm/BISMainComDTO"));
                callProFrameAdvanced("BIS-KOFIABOND","BISMainSO","selectAnnItmList",BISMainComDTO, "respAnn",true);
            }
            
           /*******************selectKrxFurList******************************************************
             * function    : selectKrxFurList
             * Description : 국채선물지수조회
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function getKrxFurList(){
            	var today = WebSquare.date.getCurrentServerDate( "yyyyMMdd" );
                setValue("reqKrxFur/BISMainComDTO/standardDt",today);
            	var BISMainComDTO = WebSquare.xml.indent(getInstanceNode("reqKrxFur/BISMainComDTO"));
                callProFrameAdvanced("BIS-KOFIABOND","BISMainSO","selectKrxFurList",BISMainComDTO, "respFur",true);
            }            
            
           /*******************makePopupZone******************************************************
             * function    : makePopupZone
             * Description : 팝업존을 생성한다.
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function makePopupZone() {
             	var popupZoneList = WebSquare.ModelUtil.findInstanceNodes("respPopupZone/root/message/BISPopupZoneListDTO/BISPopupZoneDTO");
                for (var i=0 ; i<popupZoneList.length ; i++) {
                	genPopZone.insert();
                	
                	var imageTtl = WebSquare.xml.getValue( popupZoneList[i], "imageTtl" );
                	var url = WebSquare.xml.getValue( popupZoneList[i], "url" );
                	var popupYn = WebSquare.xml.getValue( popupZoneList[i], "popupYn" );
                	var fileNm = WebSquare.xml.getValue( popupZoneList[i], "fileNm" );
                	
                	var objGrpPopZoneA2 = genPopZone.getChild( i , "grpPopZoneA2" );
                	objGrpPopZoneA2.setUserData( "url", url );
                	objGrpPopZoneA2.setUserData( "popupYn", popupYn );
                	objGrpPopZoneA2.setUserData( "urlGb", WebSquare.xml.getValue( popupZoneList[i], "urlGb" ) );
                	objGrpPopZoneA2.setUserData( "fileNm2", WebSquare.xml.getValue( popupZoneList[i], "fileNm2" ) );
                	objGrpPopZoneA2.setUserData( "originalFileNm2", WebSquare.xml.getValue( popupZoneList[i], "originalFileNm2" ) );
                	
                	var objImgPopZone = genPopZone.getChild( i , "imgPopZone" );
                	objImgPopZone.setAlt( imageTtl + " 팝업존 이미지" );
                	objImgPopZone.setSrc( "/webresource/popupZoneImage/"+fileNm);
                	
					var objImgPopZoneNavi = genPopZone.getChild( i , "imgPopZoneNavi" );
                	objImgPopZoneNavi.setAlt( "팝업"+(i+1) );
                }
                popSlide = new popSlide(genPopZone, 4000, popupZoneList.length, "imgPopZoneNavi", "grpPopZoneDiv", "imgBtnPlay");
            }
            
	       /*******************goMakeLeftMenu******************************************************
	         * function    : goMakeLeftMenu
	         * Description : Left Menu 생성
	         * Parameter   : null
	         * Return      : null
	        **************************************************************************/
	        function goMakeLeftMenu(depth1, depth2, depth3, depth4, userUrl) {
			
	        	if(depth2==null)depth2=0;
	        	
	        	var	parentDivisionId = getValue("respMenu/root/message/BISComMenuListDTO/BISComMenuDTO[depth='1' and menuIdx='"+depth1+"']/divisionId");
	        	var divisionId = getValue("respMenu/root/message/BISComMenuListDTO/BISComMenuDTO[parentDivId='"+parentDivisionId+"' and menuIdx='"+depth2+"']/divisionId");
				
	        	if(typeof depth3 == "undefined")depth3="";
	        	if(typeof depth4 == "undefined")depth4="";
	        	if(typeof userUrl == "undefined")userUrl="";
	        	
	       	 	var url = sub_url+"&parentDivisionId="+parentDivisionId+"&divisionId="+divisionId+"&parentMenuIndex="+depth1+"&menuIndex="+depth2+"&depth3="+depth3+"&depth4="+depth4+"&userUrl="+encodeURIComponent(userUrl);
	       	 	window.location.href= url;
	        }

           /*******************goLinkPage******************************************************
             * function    : goLinkPage
             * Description : 팝업존 이동
             * Parameter   : null
             * Return      : null
            **************************************************************************/
            function goLinkPage(popupYn, url, urlGb, obj) {
			
            	if(urlGb=="F"){
            		var fileNm2=obj.getUserData("fileNm2");	
            		var originalFileNm2=obj.getUserData("originalFileNm2");
            		comFileDownload("file.path.bis.popupZone", "/", fileNm2, originalFileNm2);
            	} else { 
	            	if("Y"==popupYn) {
	        	       	var top  = (($(window).height() / 2) - (768 / 2));
			            var left = (($(window).width() / 2) - (1024 / 2));
	            		window.open(url,"","width=1024px,height=768px,top="+top+",left="+left+",resizable=yes,status=yes,scrollbars=yes"); 
	            	} else {
		            	var allUrl = url.substring(url.indexOf("w2xPath=")+8); 
		            	var param;
		            	var strDiv = "divisionId=";
		            	var divIdx = allUrl.indexOf(strDiv)+strDiv.length;
		            	var divisionId = allUrl.substring(divIdx,divIdx+18);
		            	if(divisionId == null || divisionId=="") {showMsgString("잘못된 주소 입니다."); return;};
		            	var leafNode = WebSquare.ModelUtil.findInstanceNode( "respMenu/root/message/BISComMenuListDTO/BISComMenuDTO[divisionId='"+divisionId+"']" );
		            	if(leafNode == null || leafNode.length==0) {showMsgString("잘못된 주소 입니다."); return;};
		            	var depth = WebSquare.xml.getValue( leafNode , "depth" );
		            	param = WebSquare.xml.getValue( leafNode , "menuIdx" );
		            	var tmpNode=leafNode;
		            	for (var i=0 ; i<3 ; i++) {
		            		var parentDivisionId = WebSquare.xml.getValue( tmpNode , "parentDivId" );
		            		if( parentDivisionId == "*" ) {
		            			param += ",''";
		            		} else {
		            			tmpNode = WebSquare.ModelUtil.findInstanceNode( "respMenu/root/message/BISComMenuListDTO/BISComMenuDTO[divisionId='"+parentDivisionId+"']" );
		            			param = WebSquare.xml.getValue( tmpNode , "menuIdx" )+","+param;
		            		}
		            	}
		            	param += ",'"+allUrl+"'";
		            	eval("goMakeLeftMenu("+param+")");
	            	}
				}	            	
            }
            
            /**************************************************************************
             * function    : chartShow
             * Description : 챠트 속성 정보를 이용하여 챠트 구성
             * Parameter   : 
             * Return      : null
             **************************************************************************/
            function chartShow() {
				var chartNodes = WebSquare.ModelUtil.findInstanceNodes( "respIdx/root/message/BISMainIdxCompDTO/BISMainIdxChartListDTO/BISMainIdxDTO" );
				if(!WebSquare.xml.getValue( chartNodes[0] , "standardTm" )) return;
				var lineColor=['#7cb5ec', '#90ed7d', '#f7a35c','#8085e9',];
				var marginLeft;
				
				for (var i=0 ; i<chartNodes.length ; i++) {
					genChartIdx.insert();
					var seriesData = new Array();
					var category = WebSquare.xml.getValue( chartNodes[i] , "standardTm" ).split(",");
					var chartData =  nsplit(WebSquare.xml.getValue( chartNodes[i] , "totalPrfIdx" ), ",");
					var seriesName = WebSquare.xml.getValue( chartNodes[i] , "workGb" );
					marginLeft=(i==0)? 32: 45;
					
					var subOpt = {
		           			name:seriesName
		           			,data:chartData
		           			,lineWidth: 1.8
		           			,color:lineColor[i]
	            	};
					seriesData.push(subOpt);
					
					var tmpObj = genChartIdx.getChild(i, "grpChartIdx");
		            var chartObj = {
		            	grpId : tmpObj.id,
	        			title : "",
	        			series : seriesData,
	        			category : category,
	        			xTick : parseInt(category.length/4),
	        			marginLeft:marginLeft
	            	};
	            	showChart(chartObj);
				}
				//txtChartTime.setLabel( getTimeStr() );
				chartSlide = new chartSlide(genChartIdx, 5000, chartNodes.length, "grpChartIdx", "imgChartPlay", grdIdx);
            }
            
            /**************************************************************************
             * function    : getTimeStr
             * Description : 시간 문자열을 구한다.
             * Parameter   : 
             * Return      : null
             **************************************************************************/
            function getTimeStr() {
            	return WebSquare.date.getCurrentServerDate( "yyyy.MM.dd HH:mm" )+" 기준";;
            }
            
            /**************************************************************************
             * function    : showChart
             * Description : 차트 데이터를 이용해 차트를 그린다.
             * Parameter   : 
             * Return      : null
             **************************************************************************/
            function showChart(opt) {
				var chart = new Highcharts.Chart({
					chart: {	
						renderTo: opt.grpId,
						marginBottom:22,
						marginLeft:opt.marginLeft,
						marginRight:0
					},
					title: {
						text: opt.title
					},
				    legend: {
				    	enabled: false,
				    },
					xAxis: {
						categories: opt.category
						,labels: {
							formatter: function() {
								return this.value.substring(0,2) +':'+ this.value.substring(2,4);
							}
							,style: {
								fontSize:"9px"
							}
						}
						,tickInterval: opt.xTick
						,min:(opt.category.length == 1) ? 0:-0.001
					},
					yAxis: {
						title : {
							text: ""
						}
						,labels: {
			                format: '{value:,.1f}',
							style: {
								fontSize:"9px"
							},
							x:-5
						}
					},
					plotOptions: {
						series: {
							marker: {
								enabled:false
								,radius:3
							}
						}
					},
					series: opt.series,
					exporting : {
						enabled: false,
					},
				});          
            }            
            
		/**************************************************************************
		* function    : toggleMainMenu
		* Description : 주요메뉴 즐겨찾기 토글
		* Parameter   : 
		* Return      : null
		**************************************************************************/
		function toggleMainMenu(isMainMenu) {
			if(isMainMenu) {
				imgFavorMenu.setSrc( "/images/menu_tab2_c_off.png" );
				imgMainMenu.setSrc( "/images/menu_tab1_c_on.png" );
				genFavorMenu.hide();
				grpMainMenu.show();
				setCookie("bisSelectedMenu", "0");
			} else {
				imgMainMenu.setSrc( "/images/menu_tab1_c_off.png" );
				imgFavorMenu.setSrc( "/images/menu_tab2_c_on.png" );
				grpMainMenu.hide();
				genFavorMenu.show();
				setCookie("bisSelectedMenu", "1");
			}
		}
		
		/**************************************************************************
		* function    : makeFavorMenu
		* Description : 즐겨찾기 메뉴 구성
		* Parameter   : 
		* Return      : null
		**************************************************************************/
		function makeFavorMenu() {
			var favorMenuList = getCookie("bisFavorMenuList").split("|");
			genFavorMenu.removeAll();
			if(favorMenuList[0]==null || typeof favorMenuList[0]=="undefined" || favorMenuList[0]=="" ) return;
			for (var i=0 ; i<favorMenuList.length ; i++) {
				var tmpObj;
				var url=favorMenuList[i];
				genFavorMenu.insert();
				
				var tmpObj = genFavorMenu.getChild( i , "imgFavorMenu" );
				tmpObj.setSrc("/images/btn_menu_on_"+url+".gif");

				var tmpObj = genFavorMenu.getChild( i , "grpFavorMenuA" );
				tmpObj.setUserData("url", url);
			}
		}
		
		/**************************************************************************
		* function    : getFavorMenuUrl
		* Description : 즐겨찾기 URL 링크 정보 만들기
		* Parameter   : 
		* Return      : null
		**************************************************************************/
		function getFavorMenuUrl(url) {
			var retVal="";
			for (var i=0 ; i<url.length ; i+=2) {
				var idx = parseInt(url.substring(i, i+2));
				var seperator = (i==0) ? "" : ","; 
				retVal += seperator + idx;
			}
			return retVal;
		}
		
       /**************************************************************************
        * function    : openPopFavorMenu
        * Description : 즐겨찾기 관리 팝업 화면 open
        * Parameter   : null
        * Return      : null
        **************************************************************************/
        function openPopFavorMenu(){
        	var version = parseInt($.browser.version);
        	var height=($.browser.msie || (version > 8 && version < 12)) ? 560:564;
	  		openPopup2("callBackFavorMenuPop", "/xml/pop/BISMainFavorMenuPop.xml",
	                 { 
	                   width      : 668
                     , height     : height
	                 , resizable  : false
	                 , scrollbars : false }
	        );
        }
        
       /**************************************************************************
        * function    : callBackFavorMenuPop
        * Description : 즐겨찾기 관리 팝업 화면 close
        * Parameter   : null
        * Return      : null
        **************************************************************************/
        function callBackFavorMenuPop(retVal, popId){
        	setCookie("bisFavorMenuList", retVal, 30);
        	WebSquare.util.closePopup(popId);
        	makeFavorMenu();
        	toggleMainMenu(false);
        }
        
       /**************************************************************************
        * function    : changeIdxRowColor
        * Description : 즐겨찾기 관리 팝업 화면 close
        * Parameter   : null
        * Return      : null
        **************************************************************************/
        function changeIdxRowColor(idx, color, prevIdx){
        	if(prevIdx !=null)grdIdx.setRowBackgroundColor( prevIdx , "white" );        	
        	grdIdx.setRowBackgroundColor( idx , color );
        	changeIdxTime(idx+1);
        }
        
       /**************************************************************************
        * function    : changeIdxTime
        * Description : 지수 시간 변경
        * Parameter   : null
        * Return      : null
        **************************************************************************/
        function changeIdxTime(idx){
			var timeStr="";
			var standardDt=getValue("respIdx/root/message/BISMainIdxCompDTO/BISMainIdxListDTO/BISMainIdxDTO["+idx+"]/standardDt");
			var standardTm=getValue("respIdx/root/message/BISMainIdxCompDTO/BISMainIdxListDTO/BISMainIdxDTO["+idx+"]/standardTm");
			standardTm = ("JUNJJJ"==standardTm) ? "160000" : standardTm;
			if(standardDt != null && standardTm!="") {
				timeStr+=standardDt.substring(0,4)+"."+standardDt.substring(4,6)+"."+standardDt.substring(6,8)+" ";
			}
			if(standardTm != null && standardTm!="") {
				timeStr+=standardTm.substring(0,2)+":"+standardTm.substring(2,4);
			}									        			
			txtChartTime.setLabel( timeStr+" 기준" );
        }        
                
		init();
		
		/**
		* Time 스트링을 Date 객체로 변환
		* parameter time: Time 형식의 String
		* return : Date object
		*/
		function toTimeObject(time) { //parseTime(time)
			var year  = time.substr(0,4);
			var month = time.substr(4,2) - 1; // 1월=0,12월=11
			var day   = time.substr(6,2);
			var hour  = time.substr(8,2);
			var min   = time.substr(10,2);
			 
			return new Date(year,month,day,hour,min);
		}
		 
		/**
		* Time이 현재시각 이후인지 체크
		* parameter time: Time 형식의 String
		* return : true/false
		*/
		function isFutureTime(time) {
			return (toTimeObject(time) > new Date());
		}
		 
		/**
		* Time이 현재시각 이전인지 체크
		* parameter time: Time 형식의 String
		* return : true/false
		*/
		function isPastTime(time) {
			return (toTimeObject(time) < new Date());
		}

		function openPopup(stime, etime, wname, wurl, wsize, hsize, lpos, tpos){
			if(isPastTime(stime) && isFutureTime(etime)){
				window.open(wurl, wname, 'width='+ wsize +', height='+hsize+',top='+tpos+',left='+lpos);
			}
		}
		 
